def report(readings):
    total = 0
    warm = 0
    for r in readings:
        total = total + r
        if r >= 70:
            warm = warm + 1
    print(f"Warm: {warm} of {len(readings)}")
    return total / len(readings)

readings = [50, 72, 88, 64, 91, 61]
avg = report(readings)
print(f"Average: {int(avg)}")

