def validate_quantity(value):
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError("quantity must be a whole number")
    if value < 1 or value > 99:
        raise ValueError("quantity must be between 1 and 99")
    return value


for v in [12, "12", 0, 250]:
    try:
        validate_quantity(v)
        print(f"accepted: {v!r}")
    except ValueError as e:
        print(f"rejected {v!r}: {e}")

error-handling.code:
import sys

def parse_amount(text):
    try:
        return int(text)
    except ValueError as e:
        print(f"[parse] bad amount: {text!r} ({e})", file=sys.stderr)
        raise ValueError("amount must be a whole number") from e


try:
    print("ok:", parse_amount("42"))
    parse_amount("oops")
    print("BUG: bad input was swallowed!")
except ValueError as e:
    print(f"error surfaced: {e}")

