def sum_prices(values):
    total = 0.0
    for v in values:
        try:
            total += float(v)
        except (ValueError, TypeError):
            raise ValueError(f"not a price: {v!r}")
    return round(total, 2)


print("sum:", sum_prices(["3.50", "1.25", "0.75"]))
ok = sum_prices(["3.50", "1.25", "0.75"]) == 5.5
try:
    sum_prices(["3.50", "free"])
    rejected = False
except ValueError:
    rejected = True
print(f"PASS: {ok and rejected}")

files-and-io.code:
def load_settings(path):
    settings = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            key, value = line.split(":", 1)
            settings[key.strip()] = value.strip()
    return settings


with open("settings.conf", "w") as f:
    f.write("host : localhost\n# a comment\n\nport: 8080\n")
cfg = load_settings("settings.conf")
ok = cfg == {"host": "localhost", "port": "8080"}
try:
    load_settings("missing.conf")
    missing_handled = False
except FileNotFoundError:
    missing_handled = True
print("settings:", cfg)
print(f"PASS: {ok and missing_handled}")

