def safe_max(numbers):
    if not numbers:
        return None
    return max(numbers)


assert safe_max([3, 9, 4]) == 9, "normal case"
assert safe_max([7]) == 7, "single element"
assert safe_max([]) is None, "EMPTY list must return None, not crash"
assert safe_max([-5, -2, -9]) == -2, "all negatives"
print("all assertions passed")

cli-workflow.code:
def gate(args):
    if not args.get("tests_passed"):
        return "blocked: tests failing"
    if args.get("branch") != "main":
        return "blocked: wrong branch"
    if not args.get("approved"):
        return "waiting: needs approval"
    return "deploy"


cases = [
    ({"tests_passed": False, "branch": "main"}, "blocked: tests failing"),
    ({"tests_passed": True, "branch": "dev"}, "blocked: wrong branch"),
    ({"tests_passed": True, "branch": "main"}, "waiting: needs approval"),
    ({"tests_passed": True, "branch": "main", "approved": True}, "deploy"),
]
ok = all(gate(a) == exp for a, exp in cases)
for a, exp in cases:
    print(f"{a} -> {gate(a)!r}")
print(f"PASS: {ok}")

git-fundamentals.code:
def review_pr(files_changed, tests_added, description):
    if files_changed == 0:
        return "empty PR"
    if not tests_added:
        return "needs tests"
    if len(description) < 20:
        return "describe the change"
    return "ready to review"


cases = [
    (0, True, "adds the new signup validation flow", "empty PR"),
    (3, False, "adds the new signup validation flow", "needs tests"),
    (3, True, "quick fix", "describe the change"),
    (3, True, "adds the new signup validation flow", "ready to review"),
]
ok = all(review_pr(f, t, d) == exp for f, t, d, exp in cases)
for f, t, d, exp in cases:
    print(f"{f} files -> {review_pr(f, t, d)!r}")
print(f"PASS: {ok}")
